/// <summary>
/// AVA
/// </summary>
/// <param name = "_set">boolean</param>
/// <param name = "_salesQuotationTable">SalesQuotationTable</param>
/// <param name = "_markAll">NoYes</param>
/// <returns>NoYes</returns>
edit NoYes  salesMarkAll(boolean                _set,
                             SalesQuotationTable    _salesQuotationTable,
                             NoYes                  _markAll)
{
    if (_set == true)
    {
        this.formRun().dataSource(formDataSourceStr(SalesQuotationCopying,SalesQuotationLine)).last();
        this.formRun().dataSource(formDataSourceStr(SalesQuotationCopying, SalesQuotationLine)).first();
    }
    return next salesMarkAll(_set, _salesQuotationTable, _markAll);

}
